WITH base AS (SELECT id, product_id, quantity, last_restock, LAST_DAY(last_restock) AS last_restock_month_end, DATEDIFF(CURRENT_DATE(), last_restock) AS days_since_last_restock FROM inventory WHERE last_restock >= '2025-02-20') SELECT e.id, e.product_id, e.days_since_last_restock, b.product_name, b.cost, b.launch_date FROM base e INNER JOIN products b ON e.product_id = b.id WHERE b.cost > 280;
